261:     const left = keys.has('a') || keys.has('arrowleft') || touch.left;
262:     const right = keys.has('d') || keys.has('arrowright') || touch.right;
263:     const dx = (right ? 1 : 0) - (left ? 1 : 0), dz = (back ? 1 : 0) - (forward ? 1 : 0);
264:     const length = Math.hypot(dx, dz);
